class TextEditor:
    def __init__(self):
        self.text = []

    def insert(self, position, char):
        if position < 0 or position > len(self.text):
            raise IndexError("Invalid position")

        self.text.insert(position, char)

    def delete(self, position):
        if position < 0 or position >= len(self.text):
            raise IndexError("Invalid position")

        del self.text[position]

    def replace(self, start_position, end_position, new_text):
        if start_position > end_position:
            raise ValueError("Start position cannot be greater than end position")

        self.text[start_position:end_position + 1] = [new_text] * (end_position - start_position + 1)

    def get_text(self):
        return ''.join(self.text)


